+    /// Create a new recursive directory iterator at the path given.
+    pub fn walker(&self, path: &Path) -> walk::Iter {
+        let wd = WalkDir::new(path).follow_links(self.follow);
+        let mut ig = Ignore::new();
+        ig.ignore_hidden(!self.hidden);
